<script setup lang="ts">import {computed,ref} from 'vue';import {useRoute,useRouter} from 'vue-router';import AppShell from '@/components/zs/AppShell.vue';import PageHeader from '@/components/zs/PageHeader.vue';import Panel from '@/components/zs/Panel.vue';import Tabs from '@/components/zs/Tabs.vue';import ActivityTimeline from '@/components/crm/ActivityTimeline.vue';import StatusBadge from '@/components/zs/StatusBadge.vue';import ScoreBadge from '@/components/crm/ScoreBadge.vue';import ZButton from '@/components/zs/ZButton.vue';import {useCrmData} from '@/composables/useCrmData';import {setPageMeta} from '@/lib/page-meta';setPageMeta('Company Profile','CRM company relationship workspace.');const route=useRoute(),router=useRouter(),d=useCrmData(),tab=ref('Overview');const item=computed(()=>(d.companies.data.value??[]).find(x=>x.id===route.params.id)),contacts=computed(()=>(d.contacts.data.value??[]).filter(x=>x.accountId===item.value?.id)),leads=computed(()=>(d.leads.data.value??[]).filter(x=>x.accountId===item.value?.id)),acts=computed(()=>(d.activities.data.value??[]).filter(x=>x.accountId===item.value?.id));const tabs=['Overview','Contacts','Leads / Deals','Activities','Notes','Tasks','Calls','Attachments'];</script>
<template><AppShell><template v-if="item"><PageHeader :title="item.name" :description="`${item.industry} · ${item.size} employees`"><template #actions><StatusBadge :status="item.status"/><ZButton variant="outline">Edit company</ZButton><ZButton @click="router.push('/crm/leads')">Add lead</ZButton></template></PageHeader><Panel><Tabs v-model="tab" :items="tabs"/><div v-if="tab==='Overview'" class="grid gap-6 p-5 lg:grid-cols-3"><dl class="grid gap-4 text-xs lg:col-span-2 sm:grid-cols-2"><div v-for="[k,v] in Object.entries({Website:item.website,Industry:item.industry,Size:item.size,Revenue:item.revenue,Phone:item.phone,Email:item.email,Address:item.address,Owner:item.owner,'Lead source':item.source})" :key="k"><dt class="label-caps">{{k}}</dt><dd class="mt-1 text-content">{{v}}</dd></div></dl><div class="rounded-md bg-surface-sunken p-4"><p class="label-caps">Relationship</p><p class="mt-3 text-sm font-semibold text-content">{{contacts.length}} contacts</p><p class="mt-1 text-sm font-semibold text-content">{{leads.length}} leads or deals</p><p class="mt-1 text-xs text-content-muted">Last activity {{item.lastActivity}}</p></div></div><div v-else-if="tab==='Contacts'" class="divide-y divide-line px-4"><button v-for="x in contacts" :key="x.id" class="block w-full py-3 text-left" @click="router.push(`/crm/contacts/${x.id}`)"><p class="text-sm font-medium text-content">{{x.name}}</p><p class="text-xs text-content-muted">{{x.title}} · {{x.email}}</p></button></div><div v-else-if="tab==='Leads / Deals'" class="divide-y divide-line px-4"><button v-for="x in leads" :key="x.id" class="flex w-full items-center justify-between py-3 text-left" @click="router.push(`/crm/leads/${x.id}`)"><div><p class="text-sm font-medium text-content">{{x.name}}</p><p class="text-xs text-content-muted">{{x.stage}} · {{x.owner}}</p></div><ScoreBadge :score="x.score.total"/></button></div><div v-else-if="tab==='Activities'" class="p-4"><ActivityTimeline :items="acts"/></div><div v-else class="p-10 text-center text-sm text-content-muted">No {{tab.toLowerCase()}} recorded for this company.</div></Panel></template><Panel v-else body-class="p-10 text-center text-sm text-content-muted">Company not found in the active company.</Panel></AppShell></template>
